create table if not exists public.feed_posts (id uuid primary key default gen_random_uuid(), author_id uuid references auth.users(id) on delete set null, subject_area text not null, title text not null, summary text not null, content text, source_url text, tags jsonb not null default '[]'::jsonb, published_at timestamptz not null default now(), status text not null default 'published' check(status in ('draft','published','archived')));
create table if not exists public.feed_preferences (user_id uuid primary key references auth.users(id) on delete cascade, subjects jsonb not null default '[]'::jsonb, tags jsonb not null default '[]'::jsonb, updated_at timestamptz not null default now());
create index if not exists feed_posts_published_idx on public.feed_posts(status,published_at desc);
alter table public.feed_posts enable row level security; alter table public.feed_preferences enable row level security;
drop policy if exists feed_public_read on public.feed_posts; create policy feed_public_read on public.feed_posts for select using(status='published' or author_id=auth.uid());
drop policy if exists feed_author_write on public.feed_posts; create policy feed_author_write on public.feed_posts for all using(author_id=auth.uid()) with check(author_id=auth.uid());
drop policy if exists feed_preferences_owner on public.feed_preferences; create policy feed_preferences_owner on public.feed_preferences for all using(user_id=auth.uid()) with check(user_id=auth.uid());
insert into public.feed_posts(subject_area,title,summary,tags) values ('Método de estudio','Cómo reconstruir una clase difícil','Convierte apuntes, audio y lecturas en preguntas verificables.','["estudio","RAG"]'),('Matemática','Aprender con ejemplos y errores','Usa errores como señales para reforzar conceptos.','["matemática","aprendizaje"]'),('Programación','De la teoría al proyecto','Relaciona cada concepto con una pequeña prueba ejecutable.','["programación","práctica"]') on conflict do nothing;
